import type { ProofOfConcept } from '@janus/shared-kernel';

import type { FixUnderTest, FixVerification, FixVerifier } from '../../domain/fix/fix-verifier.js';
import type { GeneratedTest } from '../../domain/fix/generated-test.js';
import { judgeTests, type TestResults } from '../../domain/fix/judge-tests.js';
import type { TargetTestsPort } from '../../domain/fix/target-tests-port.js';

/**
 * The second verifier (F3.5, V2): the target's own tests plus a regression test generated by
 * code from the PoC, run on the base and on the fix and judged by judgeTests. Tests listed as
 * asserting the very flaw may break; nothing else may. The base runs once per finding.
 */
export class RegressionTestsVerifier implements FixVerifier {
  readonly name = 'regression-tests' as const;
  private readonly baseRuns = new Map<string, Promise<TestResults>>();

  constructor(
    private readonly deps: {
      readonly tests: TargetTestsPort;
      readonly generate: (poc: ProofOfConcept, findingId: string) => GeneratedTest | null;
      readonly vulnerable: (target: string, endpoint: string) => readonly string[];
    },
  ) {}

  /** The regression test of a finding, as V2 runs it and as the fix keeps it. */
  regressionTest(fix: Pick<FixUnderTest, 'poc' | 'findingId'>): GeneratedTest | null {
    return this.deps.generate(fix.poc, fix.findingId);
  }

  async verify(fix: FixUnderTest): Promise<FixVerification> {
    const regression = this.regressionTest(fix);
    if (regression === null) {
      return {
        passed: false,
        details: `no regression test can be generated from a ${fix.poc.steps.kind} PoC yet`,
      };
    }
    const run = (commit: string) =>
      this.deps.tests.run({ target: fix.target, repo: fix.repo, commit, extra: [regression] });
    const key = `${fix.findingId}@${fix.base}`;
    let base = this.baseRuns.get(key);
    if (base === undefined) {
      base = run(fix.base);
      this.baseRuns.set(key, base);
    }
    return judgeTests({
      base: await base,
      patch: await run(fix.head),
      regression: regression.name,
      vulnerable: this.deps.vulnerable(fix.target, fix.poc.endpoint),
    });
  }
}
